insert into public.exercise_library (
  name,
  slug,
  primary_muscle_group,
  secondary_muscle_groups,
  equipment,
  instructions,
  difficulty,
  is_active
) values
  ('Barbell Back Squat', 'barbell-back-squat', 'Quadriceps', array['Glutes','Hamstrings','Core'], array['Barbell','Squat Rack'], array['Set the bar across your upper back and brace your core.','Sit your hips down while keeping your knees tracking over your toes.','Descend under control, then drive through your feet to stand.'], 'intermediate', true),
  ('Goblet Squat', 'goblet-squat', 'Quadriceps', array['Glutes','Core'], array['Dumbbell','Kettlebell'], array['Hold one weight close to your chest.','Sit between your hips while keeping your chest tall.','Drive through the full foot to return to standing.'], 'beginner', true),
  ('Leg Press', 'leg-press', 'Quadriceps', array['Glutes','Hamstrings'], array['Leg Press Machine'], array['Place your feet securely on the platform.','Lower the platform until your knees reach a comfortable depth.','Press through your feet without locking your knees aggressively.'], 'beginner', true),
  ('Walking Lunge', 'walking-lunge', 'Quadriceps', array['Glutes','Hamstrings','Core'], array['Bodyweight','Dumbbell'], array['Step forward with enough distance to keep the front heel planted.','Lower both knees while keeping your torso controlled.','Push through the front foot and continue into the next step.'], 'beginner', true),
  ('Leg Extension', 'leg-extension', 'Quadriceps', array[]::text[], array['Leg Extension Machine'], array['Align your knees with the machine pivot.','Extend your legs smoothly until the quadriceps contract.','Lower the weight under control without letting the stack slam.'], 'beginner', true),
  ('Romanian Deadlift', 'romanian-deadlift', 'Hamstrings', array['Glutes','Back','Core'], array['Barbell','Dumbbell'], array['Hold the weight close to your thighs and brace your torso.','Push your hips backward with a soft bend in your knees.','Stop when your hamstrings are loaded, then drive your hips forward.'], 'intermediate', true),
  ('Conventional Deadlift', 'conventional-deadlift', 'Back', array['Glutes','Hamstrings','Quadriceps','Core'], array['Barbell'], array['Stand with the bar over the middle of your feet.','Brace your core, grip the bar, and create tension before lifting.','Push the floor away and stand tall while keeping the bar close.'], 'advanced', true),
  ('Seated Leg Curl', 'seated-leg-curl', 'Hamstrings', array[]::text[], array['Leg Curl Machine'], array['Adjust the pad so the machine aligns with your knees.','Curl your heels down and back while keeping your hips against the seat.','Return slowly until the hamstrings are lengthened.'], 'beginner', true),
  ('Barbell Hip Thrust', 'barbell-hip-thrust', 'Glutes', array['Hamstrings','Core'], array['Barbell','Bench'], array['Position your upper back against a stable bench.','Drive your hips upward while keeping your ribs controlled.','Squeeze your glutes at the top, then lower with control.'], 'intermediate', true),
  ('Glute Bridge', 'glute-bridge', 'Glutes', array['Hamstrings','Core'], array['Bodyweight','Dumbbell'], array['Lie on your back with your feet planted near your hips.','Brace your midsection and drive your hips upward.','Pause with your glutes contracted, then lower slowly.'], 'beginner', true),
  ('Standing Calf Raise', 'standing-calf-raise', 'Calves', array[]::text[], array['Calf Raise Machine','Dumbbell','Bodyweight'], array['Stand with the balls of your feet supported and heels free to move.','Rise onto your toes as high as you can without bouncing.','Lower your heels slowly into a comfortable stretch.'], 'beginner', true),
  ('Barbell Bench Press', 'barbell-bench-press', 'Chest', array['Triceps','Shoulders'], array['Barbell','Bench','Rack'], array['Set your feet firmly and keep your upper back stable on the bench.','Lower the bar toward your mid-chest with your wrists stacked.','Press the bar upward while maintaining control and full-body tension.'], 'intermediate', true),
  ('Incline Dumbbell Press', 'incline-dumbbell-press', 'Chest', array['Shoulders','Triceps'], array['Dumbbell','Adjustable Bench'], array['Set the bench to a moderate incline.','Lower the dumbbells beside your upper chest with control.','Press upward and slightly inward without banging the weights together.'], 'beginner', true),
  ('Push-Up', 'push-up', 'Chest', array['Triceps','Shoulders','Core'], array['Bodyweight'], array['Place your hands slightly wider than shoulder width.','Keep your body in a straight line as you lower your chest.','Press the floor away while keeping your hips controlled.'], 'beginner', true),
  ('Cable Chest Fly', 'cable-chest-fly', 'Chest', array['Shoulders'], array['Cable Machine'], array['Set the handles at a comfortable height and step forward.','Bring your arms together in a wide hugging motion.','Return slowly while keeping a slight bend in your elbows.'], 'beginner', true),
  ('Overhead Press', 'overhead-press', 'Shoulders', array['Triceps','Core'], array['Barbell','Dumbbell'], array['Start with the weight near shoulder height and brace your torso.','Press overhead without overextending your lower back.','Lower the weight under control to the starting position.'], 'intermediate', true),
  ('Dumbbell Lateral Raise', 'dumbbell-lateral-raise', 'Shoulders', array[]::text[], array['Dumbbell'], array['Hold the dumbbells at your sides with a slight elbow bend.','Raise your arms outward until they approach shoulder height.','Lower slowly and avoid using momentum.'], 'beginner', true),
  ('Rear Delt Fly', 'rear-delt-fly', 'Shoulders', array['Back'], array['Dumbbell','Reverse Pec Deck'], array['Hinge or position yourself so your torso is supported.','Move your arms outward while keeping a soft bend in the elbows.','Squeeze the rear shoulders, then return with control.'], 'beginner', true),
  ('Face Pull', 'face-pull', 'Shoulders', array['Back'], array['Cable Machine','Rope Attachment'], array['Set the rope near face height and step back under tension.','Pull the rope toward your face while separating your hands.','Control the return and keep your ribs from flaring.'], 'beginner', true),
  ('Pull-Up', 'pull-up', 'Back', array['Biceps','Core'], array['Pull-Up Bar'], array['Hang with a secure grip and brace your torso.','Pull your chest upward by driving your elbows down.','Lower yourself under control to a full comfortable hang.'], 'intermediate', true),
  ('Lat Pulldown', 'lat-pulldown', 'Back', array['Biceps'], array['Cable Machine','Lat Pulldown Bar'], array['Sit tall with your thighs secured under the pads.','Pull the bar toward your upper chest by driving your elbows down.','Return slowly without letting your shoulders shrug excessively.'], 'beginner', true),
  ('Barbell Bent-Over Row', 'barbell-bent-over-row', 'Back', array['Biceps','Hamstrings','Core'], array['Barbell'], array['Hinge at your hips and hold a stable torso angle.','Pull the bar toward your lower ribs while keeping it close.','Lower the bar under control without losing your brace.'], 'intermediate', true),
  ('Seated Cable Row', 'seated-cable-row', 'Back', array['Biceps'], array['Cable Machine'], array['Sit tall with your feet braced and arms extended.','Pull the handle toward your torso while driving your elbows back.','Return slowly without rounding your lower back.'], 'beginner', true),
  ('Single-Arm Dumbbell Row', 'single-arm-dumbbell-row', 'Back', array['Biceps','Core'], array['Dumbbell','Bench'], array['Support your body on a bench and keep your spine stable.','Pull the dumbbell toward your hip rather than your shoulder.','Lower until your arm is extended without twisting your torso.'], 'beginner', true),
  ('Back Extension', 'back-extension', 'Back', array['Glutes','Hamstrings'], array['Back Extension Bench'], array['Set the pad below your hips so you can hinge freely.','Lower your torso by hinging at the hips.','Squeeze your glutes to return until your body forms a straight line.'], 'beginner', true),
  ('Triceps Pushdown', 'triceps-pushdown', 'Triceps', array[]::text[], array['Cable Machine','Rope Attachment'], array['Keep your upper arms close to your sides.','Extend your elbows until your arms are straight.','Return the handle slowly without letting your shoulders move forward.'], 'beginner', true),
  ('Overhead Triceps Extension', 'overhead-triceps-extension', 'Triceps', array[]::text[], array['Dumbbell','Cable Machine'], array['Position the weight overhead with your elbows pointing forward.','Bend your elbows to lower the weight behind your head.','Extend your arms while keeping your upper arms stable.'], 'beginner', true),
  ('Barbell Curl', 'barbell-curl', 'Biceps', array['Forearms'], array['Barbell'], array['Stand tall with your elbows near your sides.','Curl the bar upward without swinging your torso.','Lower the bar slowly until your arms are extended.'], 'beginner', true),
  ('Hammer Curl', 'hammer-curl', 'Biceps', array['Forearms'], array['Dumbbell'], array['Hold the dumbbells with your palms facing each other.','Curl while keeping your elbows close to your body.','Lower slowly and keep the neutral grip throughout.'], 'beginner', true),
  ('Forearm Plank', 'forearm-plank', 'Core', array['Shoulders','Glutes'], array['Bodyweight'], array['Place your elbows under your shoulders and extend your legs.','Brace your abdomen and squeeze your glutes.','Maintain a straight line without letting your hips sag or rise.'], 'beginner', true),
  ('Dead Bug', 'dead-bug', 'Core', array['Hip Flexors'], array['Bodyweight'], array['Lie on your back with your hips and knees bent.','Brace your abdomen and slowly extend the opposite arm and leg.','Return without allowing your lower back to lift from the floor.'], 'beginner', true),
  ('Hanging Knee Raise', 'hanging-knee-raise', 'Core', array['Hip Flexors','Forearms'], array['Pull-Up Bar'], array['Hang securely with your shoulders controlled.','Raise your knees toward your torso without swinging.','Lower slowly until your legs return to the starting position.'], 'intermediate', true),
  ('Cable Crunch', 'cable-crunch', 'Core', array[]::text[], array['Cable Machine','Rope Attachment'], array['Kneel while holding the rope beside your head.','Curl your ribcage toward your pelvis using your abdominal muscles.','Return slowly without pulling primarily with your arms.'], 'beginner', true),
  ('Incline Treadmill Walk', 'incline-treadmill-walk', 'Cardio', array['Glutes','Calves','Hamstrings'], array['Treadmill'], array['Choose a sustainable speed and incline.','Walk tall with relaxed shoulders and controlled breathing.','Avoid holding the rails unless needed for safety.'], 'beginner', true),
  ('Stationary Bike', 'stationary-bike', 'Cardio', array['Quadriceps','Glutes','Calves'], array['Stationary Bike'], array['Adjust the seat so your knee remains slightly bent at the bottom.','Pedal at a controlled cadence with steady breathing.','Increase resistance gradually while maintaining smooth movement.'], 'beginner', true)
on conflict (slug) do update set
  name = excluded.name,
  primary_muscle_group = excluded.primary_muscle_group,
  secondary_muscle_groups = excluded.secondary_muscle_groups,
  equipment = excluded.equipment,
  instructions = excluded.instructions,
  difficulty = excluded.difficulty,
  is_active = excluded.is_active,
  updated_at = now();
